sys_ws_operation.operation_script:
(function process(request, response) {

    // =========================================================
    // 1. CURRENT LOGGED-IN MANAGER
    // =========================================================
    var managerId = gs.getUserID();


    // =========================================================
    // 2. INDIA DATE
    // =========================================================
    var now = new GlideDateTime();

    var indiaNow =
        new GlideDateTime(now);

    indiaNow.addSeconds(19800);

    var indiaValue =
        indiaNow.getValue();

    var today =
        indiaValue.substring(0, 10);


    // =========================================================
    // 3. FIND EMPLOYEES ASSIGNED TO THIS MANAGER
    // =========================================================
    var profile =
        new GlideRecord(
            'x_1760545_smarta_0_employee_profile'
        );

    profile.addQuery(
        'manager',
        managerId
    );

    profile.addQuery(
        'active',
        true
    );

    profile.orderBy(
        'employee'
    );

    profile.query();


    var employees = [];


    while (profile.next()) {

        var employeeId =
            profile.getValue('employee');


        var employeeName =
            profile.employee
                .getDisplayValue();


        var employeeCode =
            profile.getValue(
                'employee_code'
            );


        var department =
            profile.getValue(
                'department'
            );


        var shiftName =
            profile.shift
                .getDisplayValue();


        // =====================================================
        // FIND TODAY'S ATTENDANCE
        // =====================================================
        var attendance =
            new GlideRecord(
                'x_1760545_smarta_0_attendance'
            );


        attendance.addQuery(
            'employee',
            employeeId
        );

        attendance.addQuery(
            'attendance_date',
            today
        );

        attendance.setLimit(1);

        attendance.query();


        var attendanceData = {

            attendance_number:
                '',

            status:
                'not_checked_in',

            check_in:
                '',

            check_out:
                '',

            late_minutes:
                '0',

            working_minutes:
                '',

            scanner:
                ''
        };


        if (attendance.next()) {

            attendanceData.attendance_number =
                attendance.getValue(
                    'number'
                );


            attendanceData.status =
                attendance.getValue(
                    'status'
                );


            attendanceData.check_in =
                convertToIndiaTime(
                    attendance.getValue(
                        'check_in'
                    )
                );


            attendanceData.check_out =
                convertToIndiaTime(
                    attendance.getValue(
                        'check_out'
                    )
                );


            attendanceData.late_minutes =
                attendance.getValue(
                    'late_minutes'
                ) || '0';


            attendanceData.working_minutes =
                attendance.getValue(
                    'working_minutes'
                ) || '';


            attendanceData.scanner =
                attendance.scanner
                    .getDisplayValue();
        }


        employees.push({

            employee_id:
                employeeId,

            employee:
                employeeName,

            employee_code:
                employeeCode,

            department:
                department,

            shift:
                shiftName,

            attendance:
                attendanceData
        });
    }


    // =========================================================
    // 4. RETURN RESULT
    // =========================================================
    response.setStatus(200);

    response.setBody({

        success:
            true,

        manager:
            gs.getUserDisplayName(),

        attendance_date:
            today,

        employee_count:
            employees.length,

        employees:
            employees
    });


    // =========================================================
    // HELPER — UTC → INDIA TIME
    // =========================================================
    function convertToIndiaTime(value) {

        if (!value) {
            return '';
        }


        var dateTime =
            new GlideDateTime(value);


        dateTime.addSeconds(
            19800
        );


        return dateTime.getValue();
    }

})(request, response);
